bool character99_tables(void *data_manager,std::string *error){
    if(error)error->clear();if(g_character99_applied.load(std::memory_order_acquire))return true;if(!data_manager){if(error)*error="DataManager is null for character99_tables";return false;}
    auto &rt=il2cpp::Runtime::instance();const auto &api=rt.api();if(!api.object_new||!api.array_new||!api.string_new||!api.gc_wbarrier_set_field||!api.method_get_flags||!api.object_get_class||!api.class_get_element_class||!api.class_from_type||!api.class_is_valuetype||!api.class_value_size||!api.method_get_param||!api.method_get_return_type){if(error)*error="IL2CPP managed XML construction/signature validation API is incomplete";return false;}
    il2cpp::Runtime::ThreadScope scope(rt);if(!scope.ok()){if(error)*error=scope.error();return false;}
    std::string source;if(!assets::read_embedded_asset("assets/tables/embedded_10_character99_progression.json",source)){if(error)*error="embedded Character99 progression asset is unavailable";return false;}json::Value document;try{document=json::parse(source);}catch(const std::exception &e){if(error)*error=std::string("embedded Character99 JSON parse failed: ")+e.what();return false;}
    const auto &factors=document["factors"],&original=document["originalRecipes"],&extended=document["extendedRecipes"];if(!factors.is_array()||!original.is_array()||!extended.is_array()||factors.size()!=160||original.size()!=619||extended.size()!=117){if(error)*error="embedded Character99 asset counts do not match recovered reference dimensions";return false;}
    void *data_loader=load_ptr(data_manager,0x10);void *level_loader=data_loader?load_ptr(data_loader,0xb8):nullptr;void *growth_loader=data_loader?load_ptr(data_loader,0x1e0):nullptr;void *level_root=level_loader?load_ptr(level_loader,0x18):nullptr;if(!data_loader||!level_loader||!level_root||!growth_loader){if(error)*error="Character99 DataManager loader graph is incomplete";return false;}
    if(!g_level_factor_applied.load(std::memory_order_acquire)){
        void *factor_extension=build_from_xml_root(rt,"_AT.Core.DataSheet.Character_LevelFactorRoot","_AT.Core.DataSheet.Character_LevelFactorXmlRoot","_AT.Core.DataSheet.Character_LevelFactorXmlData",factors,false,error);if(!factor_extension)return false;
        if(!merge_factor_root(rt,level_root,factor_extension,error))return false;
        g_level_factor_applied.store(true,std::memory_order_release);
        ASTRAE_LOGI("character99 substep completed: Character_LevelFactor rows merged=%zu",factors.size());
    }
    if(!g_growth_recipe_applied.load(std::memory_order_acquire)){
        void *existing_growth_root=load_ptr(growth_loader,0x18);void *existing_growth_data=existing_growth_root?load_ptr(existing_growth_root,0x10):nullptr;void *existing_growth_dictionary=existing_growth_root?load_ptr(existing_growth_root,0x18):nullptr;
        if(existing_growth_root&&load_len(existing_growth_data)==736&&existing_growth_dictionary){g_growth_recipe_applied.store(true,std::memory_order_release);ASTRAE_LOGI("character99 substep already present: GrowthRecipe Root rows=736 dictionary=%p",existing_growth_dictionary);}
        else {
            json::Value all_recipes=json::Value::array();for(const auto &row:original.as_array())all_recipes.push_back(row);for(const auto &row:extended.as_array())all_recipes.push_back(row);
            void *growth_root=build_from_xml_root(rt,"_AT.Core.DataSheet.GrowthRecipeRoot","_AT.Core.DataSheet.GrowthRecipeXmlRoot","_AT.Core.DataSheet.GrowthRecipeXmlData",all_recipes,true,error);if(!growth_root)return false;
            void *growth_loader_class=api.object_get_class?api.object_get_class(growth_loader):nullptr;if(!growth_loader_class){if(error)*error="GrowthRecipeLoader has no runtime class";return false;}if(!set_reference_property(rt,growth_loader,growth_loader_class,"Root",growth_root,error))return false;
            void *verified_root=load_ptr(growth_loader,0x18);void *growth_data=verified_root?load_ptr(verified_root,0x10):nullptr;void *growth_dictionary=verified_root?load_ptr(verified_root,0x18):nullptr;const uint64_t growth_count=load_len(growth_data);if(!verified_root||growth_count!=736||!growth_dictionary){if(error)*error="GrowthRecipe Root verification failed: root="+(verified_root?std::string("ready"):std::string("null"))+" data_count="+std::to_string(growth_count)+" dictionary="+(growth_dictionary?"ready":"null");return false;}
            g_growth_recipe_applied.store(true,std::memory_order_release);ASTRAE_LOGI("character99 substep completed: GrowthRecipe rows=%llu dictionary=%p",static_cast<unsigned long long>(growth_count),growth_dictionary);
        }
    }
    g_character99_applied.store(true,std::memory_order_release);ASTRAE_LOGI("reference character99_tables completed: factor_extension=%zu level_factor_merged=true growth_recipes=736",factors.size());return true;
}
